const STEEL = 'http://steel:3000/v1/scrape';
const q = $('Дайджест: параметры').first().json;

async function steelScrape(url, delay = 2500) {
  return await this.helpers.httpRequest({
    method: 'POST', url: STEEL, json: true,
    body: { url, format: ['markdown'], delay },
    timeout: 55000,
  });
}

async function fetchSerp(query) {
  const input = $input.first().json;
  if (!input.error && Array.isArray(input.links) && input.links.length > 3) return input;
  const urls = [
    `https://www.bing.com/search?q=${encodeURIComponent(query)}`,
    `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`,
  ];
  let lastErr;
  for (const u of urls) {
    try {
      const r = await steelScrape.call(this, u);
      const links = Array.isArray(r.links) ? r.links : [];
      const md = (r.content && r.content.markdown) || '';
      if (links.length > 3 || md.length > 150) return r;
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error('SERP failed');
}

function decodeBing(u) {
  try {
    const m = u.match(/[?&]u=a1([^&]+)/);
    if (!m) return null;
    let b64 = m[1].replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    const dec = Buffer.from(b64, 'base64').toString('utf8');
    return /^https?:\/\//i.test(dec) ? dec : null;
  } catch (e) { return null; }
}

function decodeDdg(u) {
  try {
    const m = u.match(/[?&]uddg=([^&]+)/i);
    if (m) return decodeURIComponent(m[1]);
  } catch (e) {}
  return null;
}

function resolveUrl(u) {
  if (/bing\.com\/ck\/a/i.test(u)) return decodeBing(u);
  if (/duckduckgo\.com\/l\//i.test(u)) return decodeDdg(u);
  if (/^https?:\/\//i.test(u) && !/(bing|microsoft|msn|duckduckgo)\.com/i.test(u)) return u;
  return null;
}

function pickLinks(res) {
  const links = Array.isArray(res.links) ? res.links : [];
  const nav = /^(all|images|videos|maps|news|more|tools|next|\d+)$/i;
  const map = new Map();
  for (const l of links) {
    const real = resolveUrl(l.url || '');
    if (!real || /(bing|microsoft|msn|duckduckgo|go\.microsoft)\.com/i.test(real)) continue;
    let t = (l.text || '').replace(/https?:\/\/\S+/g, '').trim();
    if (nav.test(t) || t.length < 2) continue;
    const prev = map.get(real) || '';
    if (t.length > prev.length) map.set(real, t);
  }
  const picks = [];
  for (const [url, title] of map) { picks.push({ url, title }); if (picks.length >= 3) break; }
  return picks;
}

function snippetFromSerp(md, title) {
  const text = String(md || '');
  const esc = (title || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&').slice(0, 60);
  if (esc) {
    const re = new RegExp('##\\s*' + esc + '[\\s\\S]{0,400}', 'i');
    const m = text.match(re);
    if (m) {
      const line = m[0].replace(/^##\s*[^\n]+\n?/, '').replace(/[#>*_`|!\[\]()]+/g, ' ').replace(/\s+/g, ' ').trim();
      if (line.length > 40) return line.slice(0, 300);
    }
  }
  const para = text.split(/\n{2,}/).map(s => s.replace(/[#>*_`|!\[\]()]+/g, ' ').replace(/\s+/g, ' ').trim()).find(s => s.length > 90);
  return para ? para.slice(0, 300) : '';
}

function cleanSummary(s) {
  return String(s || '').replace(/!\[[^\]]*\]\([^)]+\)/g, '').replace(/\s+/g, ' ').trim();
}

let serp;
try { serp = await fetchSerp.call(this, q.query); } catch (e) {
  return [{ json: { chatId: q.chatId, text: '🗞 לא נמצא כלום לפי השאילתה (החיפוש לא זמין). נסה שוב בעוד דקה.' } }];
}

const serpMd = (serp.content && serp.content.markdown) || '';
const picks = pickLinks(serp);
if (!picks.length) {
  return [{ json: { chatId: q.chatId, text: '🗞 לא נמצא כלום לפי השאילתה. שלח מילות מפתח, למשל: «תקציר חדשות n8n».' } }];
}

const results = [];
for (const p of picks) {
  let summary = '';
  let realTitle = p.title;
  try {
    const r = await steelScrape.call(this, p.url, 1500);
    const md = (r && r.content && r.content.markdown) || (r && r.markdown) || '';
    const meta = (r && r.metadata) || {};
    if (meta.title) realTitle = meta.title;
    const para = String(md).split(/\n{2,}/).map(s => s.replace(/[#>*_`|!\[\]()]+/g, ' ').replace(/\s+/g, ' ').trim()).find(s => s.length > 90) || '';
    summary = cleanSummary(para).slice(0, 300);
  } catch (e) {
    summary = '';
  }
  if (!summary) summary = cleanSummary(snippetFromSerp(serpMd, p.title)).slice(0, 300);
  results.push({ title: realTitle, url: p.url, summary });
}

return [{ json: { chatId: q.chatId, query: q.query, results } }];

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const j = $input.first().json;
if (j.text) {
  return [{ json: { chatId: j.chatId, text: esc(j.text) } }];
}
const results = Array.isArray(j.results) ? j.results : [];
const parts = results.map((r, i) => {
  const head = (i + 1) + '. ' + esc(r.title || r.url);
  const sum = r.summary ? esc(r.summary) : '';
  const body = sum ? '\n— ' + sum + (sum.length >= 280 ? '…' : '') : '\n— (תיאור קצר מהחיפוש)';
  return head + '\n' + esc(r.url) + body;
});
const text = '🗞 תקציר: ' + esc(j.query || '') + '\n\n' + parts.join('\n\n');
return [{ json: { chatId: j.chatId, text: text.slice(0, 3900) } }];

const q = $('Цена: параметры').first().json;
if (!q.url) {
  return [{ json: { chatId: q.chatId, text: '💰 פורמט: מחיר <קישור למוצר או לקטלוג>' } }];
}
const res = $input.first().json;
if (res.error) {
  return [{ json: { chatId: q.chatId, text: '💰 לא הצלחתי לפתוח את הדף (timeout/אנטי-בוט): ' + String(res.error).slice(0, 150) + '\n' + q.url } }];
}
const md = (res.content && res.content.markdown) || res.markdown || '';
const meta = res.metadata || {};
const title = meta.title || q.url;

// מספרים + סימון מטבע (₪/$/€/₽ + קודים)
const re = /(?:(?<sym>[\$€₽₪])\s*)?(?<num>\d[\d\s\u00a0.,]{0,14}\d|\d)(?:\s*(?<code>₪|NIS|ILS|\$|USD|€|EUR|₽|руб\.?|RUB|ש["״]?ח))?/gi;
const found = [];
let m;
while ((m = re.exec(md)) !== null) {
  const sym = (m.groups && m.groups.sym) || '';
  const code = (m.groups && m.groups.code) || '';
  if (!sym && !code) continue; // דורשים סימן מטבע כדי לא לתפוס מספרי טלפון וכו'
  const digits = String(m.groups.num).replace(/[\s\u00a0]/g, '');
  // פרסר נקודה/פסיק כאלפיות או עשרוני
  let normalized = digits;
  if (/,\d{1,2}$/.test(normalized) && normalized.indexOf('.') === -1) {
    normalized = normalized.replace(',', '.');
  } else {
    normalized = normalized.replace(/,/g, '');
  }
  const val = parseFloat(normalized);
  if (isNaN(val) || val < 1 || val > 100000000) continue;
  let currency = '₪';
  const mark = (sym + ' ' + code).toUpperCase();
  if (/\$|USD/.test(mark)) currency = '$';
  else if (/€|EUR/.test(mark)) currency = '€';
  else if (/₽|RUB|РУБ/.test(mark)) currency = '₽';
  else if (/₪|NIS|ILS|ש/.test(mark)) currency = '₪';
  found.push({ val, currency });
}

const byCur = new Map();
for (const f of found) {
  if (!byCur.has(f.currency)) byCur.set(f.currency, new Set());
  byCur.get(f.currency).add(f.val);
}

function fmt(n, cur) {
  const rounded = Number.isInteger(n) ? n : Math.round(n * 100) / 100;
  return rounded.toLocaleString('he-IL') + ' ' + cur;
}

let text;
if (!byCur.size) {
  text = '💰 ' + title + '\nלא מצאתי מחירים בדף (ייתכן שהם נטענים ע"י סקריפטים או שהאתר חסום לבוטים).\n' + q.url;
} else {
  const parts = [];
  for (const [cur, set] of byCur) {
    const uniq = [...set].sort((a, b) => a - b);
    if (uniq.length === 1) {
      parts.push('מחיר: ' + fmt(uniq[0], cur));
    } else {
      const show = uniq.slice(0, 40).map(v => fmt(v, cur));
      parts.push('נמצאו מחירים (' + cur + '): ' + uniq.length + ' · טווח ' + fmt(uniq[0], cur) + ' — ' + fmt(uniq[uniq.length - 1], cur) + '\n' + show.join(' · ') + (uniq.length > 40 ? ' …' : ''));
    }
  }
  text = '💰 ' + title + '\n' + parts.join('\n\n') + '\n\n' + q.url;
}
return [{ json: { chatId: q.chatId, text } }];
